create function app.p2_edge_artifacts()
returns trigger
language plpgsql
set search_path to ''
as $f$
declare
  v_own uuid;
  v_old uuid;
  v_other uuid;
begin
  v_own := (select p0.office_id from public.projects p0 where p0.project_id = new.project_id);
  if tg_op = 'UPDATE' then
    v_old := (select p0.office_id from public.projects p0 where p0.project_id = old.project_id);
    if v_old is distinct from v_own then
      raise exception 'artifacts: a row cannot move to another office' using errcode = '23514';
    end if;
  end if;
  if new.requested_by_job is not null then
    v_other := (select x.office_id from public.jobs x where x.job_id = new.requested_by_job);
    if v_other is distinct from v_own then
      raise exception 'artifacts.requested_by_job names a row of another office' using errcode = '23514';
    end if;
  end if;
  return new;
end
$f$;
revoke all on function app.p2_edge_artifacts() from public, anon, authenticated, service_role;
create trigger a2_office_edges before insert or update of project_id, requested_by_job on public.artifacts
  for each row execute function app.p2_edge_artifacts();

